import{_ as a,o as t,c as i,a as o}from"./app.DLiRGumz.js";const g=JSON.parse('{"title":"Operational Learning Assets (WP-12008)","description":"","frontmatter":{},"headers":[],"relativePath":"guides/OPERATIONAL_LEARNING.md","filePath":"guides/OPERATIONAL_LEARNING.md","lastUpdated":1771753292000}'),r={name:"guides/OPERATIONAL_LEARNING.md"};function n(s,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="operational-learning-assets-wp-12008" tabindex="-1">Operational Learning Assets (WP-12008) <a class="header-anchor" href="#operational-learning-assets-wp-12008" aria-label="Permalink to &quot;Operational Learning Assets (WP-12008)&quot;">​</a></h1><h2 id="quick-start-runbook" tabindex="-1">Quick Start Runbook <a class="header-anchor" href="#quick-start-runbook" aria-label="Permalink to &quot;Quick Start Runbook&quot;">​</a></h2><ol><li><strong>Login</strong>: <code>thegent cliproxy login &lt;provider&gt;</code></li><li><strong>Negotiate</strong>: <code>thegent govern negotiate csm csm-v1</code></li><li><strong>Plan</strong>: <code>thegent plan dag list</code></li><li><strong>Execute</strong>: <code>thegent orchestrate run &quot;task prompt&quot;</code></li></ol><h2 id="anti-fatigue-coaching-cards" tabindex="-1">Anti-Fatigue Coaching Cards <a class="header-anchor" href="#anti-fatigue-coaching-cards" aria-label="Permalink to &quot;Anti-Fatigue Coaching Cards&quot;">​</a></h2><ul><li><strong>Card 1: Correlation First</strong>: Always check <code>correlation_id</code> before escalating. Multiple failures with the same ID are likely one root cause.</li><li><strong>Card 2: Threshold Check</strong>: If <code>thegent observe traffic</code> shows fallback &gt; 15%, prioritize adapter tuning over new task runs.</li><li><strong>Card 3: Sandbox Safety</strong>: Use <code>thegent observe replay --sandbox</code> for all what-if simulations to prevent state mutation.</li></ul><h2 id="operator-checklist" tabindex="-1">Operator Checklist <a class="header-anchor" href="#operator-checklist" aria-label="Permalink to &quot;Operator Checklist&quot;">​</a></h2><ul><li>[ ] Contract version negotiated and matching client capability.</li><li>[ ] System load level is &quot;normal&quot; or &quot;spike&quot; (not &quot;surge&quot;).</li><li>[ ] No pending handoff confirmations for current owner.</li><li>[ ] Confidence scores active for critical lane tasks.</li></ul><h2 id="enterprise-grade-intuition-phase-12" tabindex="-1">Enterprise-Grade Intuition (Phase 12) <a class="header-anchor" href="#enterprise-grade-intuition-phase-12" aria-label="Permalink to &quot;Enterprise-Grade Intuition (Phase 12)&quot;">​</a></h2><h3 id="signal-vs-noise" tabindex="-1">Signal vs. Noise <a class="header-anchor" href="#signal-vs-noise" aria-label="Permalink to &quot;Signal vs. Noise&quot;">​</a></h3><ul><li><strong>High-Severity Escalation</strong>: If the <code>EscalationManager</code> triggers a cooldown, transition to <strong>Critical Lane</strong> mode. Only <code>critical</code> alerts will surface.</li><li><strong>Explainability</strong>: Use <code>thegent observe explain &lt;run-id&gt;</code> to fetch the v2.0 explanation bundle. Look for the <code>evidence_links</code> field to verify the decision&#39;s foundation.</li><li><strong>Evidence Integrity</strong>: All evidence bundles exported via <code>EvidenceGraph</code> are tamper-proofed with deterministic SHA-256 hashes. Verify the <code>bundle_checksum</code> before starting forensic analysis.</li></ul><h3 id="federation-awareness-phase-13" tabindex="-1">Federation Awareness (Phase 13) <a class="header-anchor" href="#federation-awareness-phase-13" aria-label="Permalink to &quot;Federation Awareness (Phase 13)&quot;">​</a></h3><ul><li><strong>Namespace Lookup</strong>: Policies are resolved via <code>org.project.env</code>. If a policy is missing, it falls back to <code>org.default.default</code>.</li><li><strong>Conflict Arbitration</strong>: When multiple namespaces apply, the <strong>most restrictive</strong> policy wins (e.g., if one requires human-in-loop, it becomes mandatory).</li></ul><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p><strong>Extended on:</strong> 2026-02-17 <strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>',24)])])}const p=a(r,[["render",n]]);export{g as __pageData,p as default};
